import React, { useEffect, useState } from 'react';
import '../styles/home.css';
import { FaHeart, FaComment } from 'react-icons/fa';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    // Dummy data
    setPosts([
      { id: 1, user: 'Aman', content: 'Just got placed at Amazon!', likes: 10, comments: 2 },
      { id: 2, user: 'Simran', content: 'Join my DSA bootcamp!', likes: 5, comments: 1 },
    ]);
    setSuggestions([
      { id: 1, name: 'Harpreet Singh', branch: 'CSE' },
      { id: 2, name: 'Mandeep Kaur', branch: 'IT' },
    ]);
  }, []);

  return (
    <div className="home-page">
      <div className="sidebar">
        <h2 className="logo">CampusGram</h2>
        <ul className="nav-links">
          <li>🏠 Home</li>
          <li>🔍 Search</li>
          <li>💬 Messages</li>
          <li>❤️ Notifications</li>
          <li>➕ Create</li>
          <li>👤 Profile</li>
        </ul>
      </div>

      <div className="main-section">
        {/* Header */}
        <div className="header">
          {[1, 2, 3, 4, 5, 6, 7].map((_, index) => (
            <div key={index} className="story-circle"></div>
          ))}
        </div>

        {/* Feed */}
        <div className="feed">
          {posts.map(post => (
            <div className="post-card" key={post.id}>
              <h4>{post.user}</h4>
              <p>{post.content}</p>
              <div className="post-actions">
                <span><FaHeart /> {post.likes}</span>
                <span><FaComment /> {post.comments}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="rightbar">
        <div className="profile-section">
          <img src="https://via.placeholder.com/40" alt="user" />
          <div>
            <strong>kaur_ramgariah01</strong>
            <p>Taranpreet</p>
          </div>
        </div>

        <div className="suggestions">
          <h4>Suggested for you</h4>
          {suggestions.map(s => (
            <div className="suggestion" key={s.id}>
              <div>
                <p>{s.name}</p>
                <small>{s.branch}</small>
              </div>
              <button>Follow</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;
